// ---------------------------------------------------------------------------
// Inline SAC-convention token contract (stellar-tokens)
// ---------------------------------------------------------------------------

#[contract]
pub struct TokenContract;

#[contractimpl]
impl TokenContract {
    pub fn __constructor(
        e: &Env,
        owner: Address,
        initial_supply: i128,
        decimals: u32,
        name: SorobanString,
        symbol: SorobanString,
    ) {
        Base::set_metadata(e, decimals, name, symbol);
        Base::mint(e, &owner, initial_supply);
    }

    pub fn mint(e: &Env, to: Address, amount: i128) {
        Base::mint(e, &to, amount);
    }

    pub fn set_fail_transfers(e: &Env, fail: bool) {
        e.storage()
            .instance()
            .set(&soroban_sdk::symbol_short!("fail"), &fail);
    }
}

#[contractimpl(contracttrait)]
impl FungibleToken for TokenContract {
    type ContractType = Base;

    fn transfer(e: &Env, from: Address, to: soroban_sdk::MuxedAddress, amount: i128) {
        let fail: bool = e
            .storage()
            .instance()
            .get(&soroban_sdk::symbol_short!("fail"))
            .unwrap_or(false);
        if fail {
            panic!("transfers disabled");
        }
        Base::transfer(e, &from, &to, amount);
    }
}

